        // ══════════════════════════════════════════════════════════════════════
        // SHUTDOWN TIMER
        // ══════════════════════════════════════════════════════════════════════

        private System.Windows.Threading.DispatcherTimer? _shutdownTimer;
        private DateTime _shutdownTargetTime;
        private int      _shutdownTotalSeconds;
        private void InitShutdownPanel()
        {
            // Just refresh display — no auto-start
        }

        // Shutdown timer now lives inside the unified compact widget.
        private void EnsureShutdownWidget()
        {
            // Timer notification goes to compact widget
            if (_compactWidget != null)
            {
                _compactWidget.SetTimerActive(true, _shutdownTargetTime, _shutdownTotalSeconds);
                if (!_compactWidget.IsVisible) _compactWidget.Show();
            }
        }

        private void ShutdownPreset_Click(object sender, RoutedEventArgs e)
        {
            if (sender is Button btn && int.TryParse(btn.Tag?.ToString(), out int mins))
                TxtShutdownMinutes.Text = mins.ToString();
        }

        private void StartShutdownTimer_Click(object sender, RoutedEventArgs e)
        {
            if (!int.TryParse(TxtShutdownMinutes.Text.Trim(), out int mins) || mins <= 0)
            {
                AppDialog.Show(LanguageService.S("Msg", "ShutdownMinutesInvalid"), "SMD Win", AppDialog.Kind.Warning);
                return;
            }

            // A forced shutdown closes programs without saving — confirmation with the exact time
            if (!AppDialog.Confirm(
                    string.Format(_LS("Tools", "ShutdownConfirmFmt"),
                                  DateTime.Now.AddMinutes(mins).ToString("HH:mm"), mins),
                    "Shutdown Timer")) return;

            // Schedule Windows shutdown: /s=shutdown /f=force /t=seconds
            int secs = mins * 60;
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName  = "shutdown",
                Arguments = $"/s /f /t {secs}",
                CreateNoWindow     = true,
                UseShellExecute    = false,
            });

            _shutdownTotalSeconds = secs;
            _shutdownTargetTime   = DateTime.Now.AddSeconds(secs);
            SMDWin.Services.ToolActivityLog.Add("Shutdown timer", $"set for {_shutdownTargetTime:HH:mm}", "info");

            BtnStartShutdown.Visibility  = Visibility.Collapsed;
            TxtShutdownCountdown.Visibility = Visibility.Visible;   // the clock appears only while it runs
            TxtShutdownIdle.Visibility = Visibility.Collapsed;
            BtnCancelShutdown.Visibility = Visibility.Visible;
            BtnCancelShutdown.IsEnabled  = true;
            TxtShutdownStatus.Text      = string.Format(_LS("Tools", "TimerActiveUntilFmt"),
                                          _shutdownTargetTime.ToString("HH:mm:ss"));


            _shutdownTimer = new System.Windows.Threading.DispatcherTimer
            {
                Interval = TimeSpan.FromSeconds(1)
            };
            _shutdownTimer.Tick += OnShutdownTick;
            _shutdownTimer.Start();
            OnShutdownTick(null, EventArgs.Empty); // immediate update

            EnsureShutdownWidget();
        }

        private void OnShutdownTick(object? sender, EventArgs e)
        {
            var remaining = _shutdownTargetTime - DateTime.Now;
            if (remaining.TotalSeconds <= 0)
            {
                TxtShutdownCountdown.Text = "00:00:00";
                TxtShutdownStatus.Text    = _LS("Tools", "TimerFinished");
                _shutdownTimer?.Stop();
                UpdateShutdownProgress(1.0);
                if (ShutdownProgressTrack != null) ShutdownProgressTrack.Visibility = Visibility.Collapsed;
                _compactWidget?.SetTimerActive(false, DateTime.MinValue, 1);
                _shutdownTotalSeconds = 0;
                return;
            }

            var total = TimeSpan.FromSeconds(_shutdownTotalSeconds);
            TxtShutdownCountdown.Text = remaining.ToString(@"hh\:mm\:ss");
            TxtShutdownETA.Text       = $"turns off at {_shutdownTargetTime:HH:mm}";
            TxtShutdownETA.Visibility = Visibility.Visible;

            double pct = 1.0 - remaining.TotalSeconds / _shutdownTotalSeconds;
            UpdateShutdownProgress(pct);

            // Clock colour: normal → attention (under 10 min) → critical (under 3 min)
            TxtShutdownCountdown.SetResourceReference(TextBlock.ForegroundProperty,
                remaining.TotalMinutes > 10 ? "TextPrimaryBrush" : remaining.TotalMinutes > 3 ? "StatusWarningBrush" : "StatusErrorBrush");

            // Update compact widget timer
            _compactWidget?.SetTimerActive(true, _shutdownTargetTime, _shutdownTotalSeconds);
        }

        // Called directly from the compact widget as fallback if event has no subscribers
        public void CancelShutdownFromWidget()
        {
            CancelShutdownTimer_Click(this, new RoutedEventArgs());
        }

        /// <summary>Called by the compact widget when user clicks a metric to navigate to its tab.</summary>
        public Task NavigateToPublic(string panel) => NavigateTo(panel);

        public Task ShowWindowsInfoDialogPublic() => ShowWindowsInfoDialogAsync();

        public void OpenFirewallPublic() => OpenFirewall_Click(this, new RoutedEventArgs());

        public SMDWin.Services.ThrottleSnapshot? LastThrottleSnapshotPublic => _lastThrottle;
        /// <summary>The last temperatures read (null if too old) — for the Health Check.</summary>
        public SMDWin.Services.TempSnapshot? LastTempSnapshotPublic => _lastTempSnap;

        private void CancelShutdownTimer_Click(object sender, RoutedEventArgs e)
        {
            _shutdownTimer?.Stop();
            _shutdownTimer = null;

            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName  = "shutdown",
                Arguments = "/a",
                CreateNoWindow     = true,
                UseShellExecute    = false,
            });

            BtnStartShutdown.Visibility  = Visibility.Visible;
            BtnCancelShutdown.Visibility = Visibility.Collapsed;
            BtnCancelShutdown.IsEnabled = false;
            TxtShutdownCountdown.Text   = "";
            TxtShutdownCountdown.Visibility = Visibility.Collapsed;
            TxtShutdownIdle.Visibility = Visibility.Visible;
            if (_shutdownTotalSeconds > 0) SMDWin.Services.ToolActivityLog.Add("Shutdown timer", "cancelled", "info");
            _shutdownTotalSeconds = 0;
            TxtShutdownStatus.Text      = _LS("Tools", "TimerCancelled");
            TxtShutdownETA.Text         = "";
            TxtShutdownETA.Visibility   = Visibility.Collapsed;   // an empty row would push "Off" above the centre of the clock
            UpdateShutdownProgress(0);
            if (ShutdownProgressTrack != null) ShutdownProgressTrack.Visibility = Visibility.Collapsed;

            // Clear timer from compact widget
            _compactWidget?.SetTimerActive(false, DateTime.MinValue, 1);
        }
    }
